SELECT p.id AS program_id, p.title AS title, p.location_text AS location_text, p.spot_id AS spot_id, p.start_at AS start_at, p.end_at AS end_at, p.apply_open_at AS apply_open_at, p.apply_close_at AS apply_close_at, p.capacity AS capacity, AS remaining_seats, p.fee AS fee, p.overnight AS overnight, p.status AS status FROM program p WHERE p.status = 'SCHEDULED'
AND #{now} < p.apply_open_at
AND p.apply_open_at <= #{now} AND #{now} < p.apply_close_at
AND p.apply_close_at <= #{now}
ORDER BY p.start_at, p.id LIMIT #{limit} OFFSET #{offset}

SELECT a.id AS application_id, a.member_id AS member_id, m.nickname AS nickname, a.status AS status, a.payment_due_at AS payment_due_at, a.confirmed_at AS confirmed_at, a.canceled_at AS canceled_at, a.cancel_reason AS cancel_reason, a.review_requested_at AS review_requested_at, a.created_at AS created_at FROM program_application a JOIN member m ON m.id = a.member_id WHERE a.program_id = #{programId}
AND a.status = #{status}
ORDER BY a.id LIMIT #{limit} OFFSET #{offset}

SELECT a.id AS application_id, a.status AS status, a.payment_due_at AS payment_due_at, a.confirmed_at AS confirmed_at, a.canceled_at AS canceled_at, a.cancel_reason AS cancel_reason, a.created_at AS created_at, p.id AS program_id, p.title AS title, p.location_text AS location_text, p.start_at AS start_at, p.end_at AS end_at, p.fee AS fee, p.status AS program_status, p.apply_open_at AS apply_open_at, p.apply_close_at AS apply_close_at FROM program_application a JOIN program p ON p.id = a.program_id WHERE a.member_id = #{memberId}
AND a.status = #{status}
ORDER BY a.id DESC LIMIT #{limit} OFFSET #{offset}
